arguments.command:
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The key must only use A-Z a-z 0-9 _ . - (Cirrus function URL rejects other keys with 400).
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing. The legacy form (?/name) is still accepted.
action_from_query() {
  case "$1" in
    action=*) echo "${1#action=}" | cut -d'&' -f1 ;;
    /*) echo "${1#/}" ;;
  esac
}
EOF
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?/save' | grep -q '^200 save' || { echo "handle legacy"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
# every rendered form URL must have only characters allowed in query keys
for f in event seat refund; do
  bash bin/render $f | grep -o 'action="[^"]*"' | sed 's/action="?//; s/"$//' | while read -r kv; do
    k=${kv%%=*}; echo "$k" | grep -qE '^[A-Za-z0-9_.-]+$' || { echo "bad key $k"; exit 1; }
  done || fail=1
done
bash bin/handle POST '/orders/1/refund?action=refund' | grep -q '^200 refund' || { echo "refund"; fail=1; }
bash bin/handle POST '/events/1/seats?action=assign' | grep -q '^200 assign' || { echo "assign"; fail=1; }
exit $fail
EOF
sed -i 's|`?/<操作名>`|`?action=<操作名>`（クエリのキーは `A-Z a-z 0-9 _ . -` のみ。`?/<操作名>` は旧形式で受理のみ）|' docs/framework.md
bash scripts/verify.sh; echo rc=$?; bash bin/render event; git status --short

